784	    /**
785	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
786	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
787	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
788	     * renders as a 429 Too Many Requests response.
789	     *
790	     * @param date the registration date of the owner being created (today)
791	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
792	     */
793	    private void rejectDailyRegistrationLimit(LocalDate date) {
794	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
795	            throw new DailyOwnerRegistrationLimitException(date);
796	        }
797	    }
798	
799	    /**
800	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
801	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
802	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
803	     * day's owners identically.
804	     *
805	     * @param date the registration date to count owners for
806	     * @return the number of existing owners registered on that day
807	     */
808	    private long ownersRegisteredOn(LocalDate date) {
809	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
810	    }
811	
812	    /**
813	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
814	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
815	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
816	     */
817	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
818	
819	    /**
820	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
821	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
822	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
823	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
824	     * without a registration date, such as seed data) is never flagged.
825	     *
826	     * @param date the owner's registration date (the day it was created), or {@code null}
827	     * @return {@code true} if the day already holds more than the warning threshold of owners
828	     */
829	    private boolean bulkSignupWarning(LocalDate date) {
830	        if (date == null) {
831	            return false;
832	        }
833	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
834	    }
835	
836	    /**
837	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
838	     * The identity key is the SHA-256 hex digest over
839	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
840	     * {@link #identityKey(Owner)}) and is the single duplicate check: it subsumes the former separate
841	     * telephone, email and household duplicate blocks. Because the telephone is part of the key, two
842	     * owners with the same last name and postcode but <em>different</em> telephones have different
843	     * identity keys and are both allowed (the second is surfaced instead as a soft
844	     * {@code possibleDuplicate}, see {@link #possibleDuplicateOf(Owner)}); only an exact full-key match
845	     * is a duplicate. Owners flagged deleted are ignored (see {@link #findExistingOwner(Function, String)}),
846	     * and the email-domain blocklist has already been applied earlier in the create flow. A collision is
